HOST="import hashlib,json,pathlib,subprocess,sys,urllib.request\nj=json.load(sys.stdin);base=pathlib.Path('/data/wio/sglang-mech36-20261018');assert json.loads((base/'owner.json').read_text())['task']=='sglang-pd-spec-36'\nx=json.loads(subprocess.run(['docker','inspect','--format','{{json .}}',j['container']],capture_output=True,text=True,check=True,timeout=25).stdout);assert x['Id']==j['container_id'] and x['Config']['Labels']['task']=='sglang-pd-spec-36' and x['Config']['Labels']['run']==j['run'] and x['State']['Running']\nopener=urllib.request.build_opener(urllib.request.ProxyHandler({}))\nwith opener.open('http://172.16.12.'+str(j['node'])+':'+str(39044 if j['node']==44 else 39046)+'/ready',timeout=5) as response:assert response.status==200\nv={'node':j['node'],'container_id':x['Id'],'state':x['State'],'pure_ready':200,'read_only':True,'inference_requests':0}\nif j['node']==44:\n model=pathlib.Path(j['model_path']);assert model.resolve().is_relative_to(base.resolve());v['model_metadata']={}\n for name in ['config.json','generation_config.json','tokenizer_config.json']:\n  f=model/name\n  if f.is_file():data=f.read_bytes();assert len(data)<1024**2;v['model_metadata'][name]={'sha256':hashlib.sha256(data).hexdigest(),'json':json.loads(data)}\n\nwith opener.open('http://172.16.12.'+str(j['node'])+':'+str(39044 if j['node']==44 else 39046)+'/server_info',timeout=10) as response:info=json.load(response)\nv['selected_runtime_fields']={k:value for k,value in info.items() if any(key in k for key in ['deterministic','sampling','logprob','speculative','cuda_graph','overlap','seed'])}\nprint(json.dumps(v))\n"
IMAGE="import hashlib,json,pathlib,subprocess,sys\nroot=pathlib.Path('/sgl-workspace/sglang');v={'sources':{},'control_matches':[],'Torch_imported':'torch' in sys.modules,'NPU_device_nodes_absent':not any(pathlib.Path('/dev').glob('davinci*'))}\nnames=['python/sglang/srt/speculative/eagle_worker_common.py','python/sglang/srt/layers/logprob_processor.py','python/sglang/srt/speculative/base_spec_worker.py','python/sglang/srt/managers/scheduler.py','python/sglang/srt/server_args.py']\nfor name in names:\n p=root/name\n if not p.is_file():v['sources'][name]={'exists':False};continue\n data=p.read_bytes();q=subprocess.run(['git','-c','safe.directory='+str(root),'show','HEAD:'+name],capture_output=True,cwd=root,timeout=15);assert q.returncode==0 and q.stdout==data\n v['sources'][name]={'exists':True,'sha256':hashlib.sha256(data).hexdigest(),'matches_HEAD':True,'source':data.decode()}\nfor p in sorted((root/'python/sglang/srt').rglob('*.py')):\n if p.stat().st_size>1500000:continue\n data=p.read_bytes();lines=data.decode(errors='replace').splitlines();rows=[]\n for i,line in enumerate(lines):\n  if any(k in line for k in ['def get_internal_state(', 'def flush_cache(', 'def _handle_deterministic', 'def _set_deterministic', 'def _handle_enable_deterministic', 'logprobs are not supported', 'logprobs is not supported']):rows.append({'line':i+1,'context':'\\n'.join(lines[max(0,i-4):i+85])})\n if rows:v['control_matches'].append({'path':str(p),'sha256':hashlib.sha256(data).hexdigest(),'contexts':rows})\nassert not v['Torch_imported'] and v['NPU_device_nodes_absent'];print(json.dumps(v))\n"
